<!-- generated by studio，请勿手工修改。 -->
<template>
  <ContentWrap>
    <el-form ref="queryFormRef" :inline="true" :model="queryParams" class="-mb-15px">
        <el-form-item label="用户名" prop="username">
          <el-input v-model="queryParams.username" clearable placeholder="请输入用户名" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="订单编号" prop="orderNumber">
          <el-input v-model="queryParams.orderNumber" clearable placeholder="请输入订单编号" @keyup.enter="handleQuery" />
        </el-form-item>
      <el-form-item>
        <el-button @click="handleQuery"><Icon class="mr-5px" icon="ep:search" />查询</el-button>
        <el-button @click="resetQuery"><Icon class="mr-5px" icon="ep:refresh" />重置</el-button>
          <el-button type="primary" @click="openForm('create')">
            <Icon class="mr-5px" icon="ep:plus" />新增
          </el-button>
          <el-button :loading="exportLoading" type="success" @click="handleExport">
            <Icon class="mr-5px" icon="ep:download" />导出
          </el-button>
          <el-button :disabled="checkedIds.length === 0" type="danger" @click="handleDeleteBatch">
            <Icon class="mr-5px" icon="ep:delete" />批量删除
          </el-button>
      </el-form-item>
    </el-form>
  </ContentWrap>

  <ContentWrap>
    <el-table v-loading="loading" :data="rows" @selection-change="handleSelectionChange">
        <el-table-column align="center" type="selection" width="55" />
      <el-table-column align="center" label="行号" width="90">
        <template #default="scope">{{ (queryParams.pageNo - 1) * queryParams.pageSize + scope.$index + 1 }}</template>
      </el-table-column>
        <el-table-column label="用户名" prop="username" min-width="120" show-overflow-tooltip />
        <el-table-column label="支付金额" prop="paymentAmount" min-width="120" show-overflow-tooltip />
        <el-table-column align="center" :formatter="dateFormatter" label="支付时间" prop="paymentTime" width="180" />
        <el-table-column align="center" :formatter="dateFormatter" label="到期时间" prop="expirationTime" width="180" />
        <el-table-column label="订单编号" prop="orderNumber" min-width="120" show-overflow-tooltip />
        <el-table-column label="账户类型" prop="accountType" min-width="120" show-overflow-tooltip />
        <el-table-column label="业务描述" prop="businessDescription" min-width="120" show-overflow-tooltip />
        <el-table-column label="订单支付状态" prop="orderPaymentStatus" min-width="120" show-overflow-tooltip />
        <el-table-column align="center" fixed="right" label="操作" width="160">
          <template #default="scope">
            <el-button link type="primary" @click="openDetail(scope.row.id)">查看</el-button>
            <el-button link type="primary" @click="openForm('update', scope.row.id)">编辑</el-button>
            <el-button link type="danger" @click="handleDelete(scope.row.id)">删除</el-button>
          </template>
        </el-table-column>
    </el-table>
    <Pagination v-model:limit="queryParams.pageSize" v-model:page="queryParams.pageNo" :total="total" @pagination="getList" />
  </ContentWrap>

  <BoxunAccountPaymentForm ref="formRef" @success="getList" />
  <BoxunAccountPaymentDetail ref="detailRef" />
</template>

<script setup lang="ts">
import { dateFormatter } from '@/utils/formatTime'
import request from '@/config/axios'
import download from '@/utils/download'
import * as BoxunAccountPaymentApi from './BoxunAccountPaymentApi'
import BoxunAccountPaymentForm from './BoxunAccountPaymentForm.vue'
import BoxunAccountPaymentDetail from './BoxunAccountPaymentDetail.vue'

type BoxunAccountPaymentRow = Awaited<ReturnType<typeof BoxunAccountPaymentApi.getBoxunAccountPaymentPage>>['list'][number]
type EntityId = string | number

defineOptions({ name: 'BoxunAccountPayment' })

const message = useMessage()
const { t } = useI18n()
const loading = ref(false)
const total = ref(0)
const rows = ref<BoxunAccountPaymentRow[]>([])
const queryFormRef = ref()
const queryParams = reactive({
  pageNo: 1,
  pageSize: 10,
  username: '',
  orderNumber: ''
})



const getList = async () => {
  loading.value = true
  try {
    const data = await BoxunAccountPaymentApi.getBoxunAccountPaymentPage(queryParams)
    rows.value = data.list
    total.value = Number(data.total)
  } finally {
    loading.value = false
  }
}

const handleQuery = () => {
  queryParams.pageNo = 1
  getList()
}

const resetQuery = () => {

  queryFormRef.value?.resetFields()

  handleQuery()
}

const formRef = ref()
const openForm = (type: 'create' | 'update', id?: EntityId) => {
  formRef.value?.open(type, id, type === 'create' ? undefined : undefined)
}


const detailRef = ref()
const openDetail = (id: EntityId) => {
  detailRef.value?.open(id)
}



const handleDelete = async (id?: EntityId) => {
  if (id === undefined) return
  await message.delConfirm()
  await BoxunAccountPaymentApi.deleteBoxunAccountPayment(id)
  message.success(t('common.delSuccess'))
  await getList()
}

const checkedIds = ref<EntityId[]>([])
const handleSelectionChange = (rows: BoxunAccountPaymentRow[]) => {
  checkedIds.value = rows.map((row) => row.id).filter((id): id is EntityId => id !== undefined)
}

const handleDeleteBatch = async () => {
  await message.delConfirm()
  await BoxunAccountPaymentApi.deleteBoxunAccountPaymentList(checkedIds.value)
  message.success(t('common.delSuccess'))
  checkedIds.value = []
  await getList()
}
const exportLoading = ref(false)
const handleExport = async () => {
  await message.exportConfirm()
  exportLoading.value = true
  try {
    const data = await request.download({ url: '/boxun/account-payment/export-excel', params: queryParams })
    download.excel(data, 'boxunAccountPayment.xls')
  } finally {
    exportLoading.value = false
  }
}

onMounted(getList)
</script>
